package com.xyz.question_bank_management_system.modules.competency.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;import com.xyz.question_bank_management_system.exception.*;import com.xyz.question_bank_management_system.modules.competency.entity.*;import com.xyz.question_bank_management_system.modules.competency.mapper.*;import com.xyz.question_bank_management_system.modules.competency.service.OccupationSkillLevelAnalysisService;import com.xyz.question_bank_management_system.modules.llm.entity.QbLlmCall;import com.xyz.question_bank_management_system.modules.llm.service.LlmService;import com.xyz.question_bank_management_system.util.HashUtil;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class OccupationSkillLevelAnalysisServiceImpl implements OccupationSkillLevelAnalysisService {private final OccupationMapper occupationMapper;private final OccupationSkillMapper occupationSkillMapper;private final SkillMapper skillMapper;private final OccupationSkillLevelAnalysisMapper mapper;private final LlmService llmService;private final ObjectMapper objectMapper;
 @Override @Transactional public OccupationSkillLevelAnalysis analyze(Long occupationId,String providerKey,Long operatorId){Occupation occupation=occupationMapper.selectById(occupationId);if(occupation==null)throw BizException.of(ErrorCode.NOT_FOUND,"occupation not found");List<Map<String,Object>> skills=occupationSkillMapper.selectByOccupationId(occupationId).stream().map(row->{Skill s=skillMapper.selectById(row.getSkillId());return Map.<String,Object>of("skillId",row.getSkillId(),"skillName",s==null?"":s.getNameZh(),"requirementType",row.getRequirementType(),"importance",row.getImportanceScore());}).toList();if(skills.isEmpty())throw BizException.of(ErrorCode.CONFLICT,"occupation has no skills");String input=json(Map.of("occupationId",occupationId,"occupationName",occupation.getNameZh(),"skills",skills));OccupationSkillLevelAnalysis record=new OccupationSkillLevelAnalysis();record.setBatchCode("OSLA-"+UUID.randomUUID().toString().replace("-",""));record.setOccupationId(occupationId);record.setRoundNo(1);record.setProviderKey(providerKey);record.setInputJson(input);record.setCreatedBy(operatorId);String prompt="Return strict JSON only: {\"levels\":[{\"skillId\":number,\"level\":\"BEGINNER|INTERMEDIATE|ADVANCED\",\"reason\":string}]}. Assess target job skill level candidates only; do not publish or modify standards. Input="+input;QbLlmCall call=llmService.chatCompletion(5,occupationId,prompt,providerKey,operatorId);record.setModelName(call.getModelName());String content=llmService.extractContent(call.getResponseText());try{if(call.getCallStatus()==null||call.getCallStatus()!=1||content==null)throw new IllegalArgumentException("provider failed");objectMapper.readTree(content);record.setOutputJson(content);record.setStatus("PENDING_REVIEW");}catch(Exception ex){record.setOutputJson(content);record.setStatus("FAILED");record.setErrorMessage(shortError(ex));}mapper.insert(record);return record;}
 @Override public List<OccupationSkillLevelAnalysis> list(Long occupationId,int limit){return mapper.list(occupationId,Math.max(1,Math.min(100,limit)));}
 private String json(Object value){try{return objectMapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}private String shortError(Exception e){String s=Objects.toString(e.getMessage(),e.getClass().getSimpleName());return s.length()>900?s.substring(0,900):s;}}
